"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

P1 v0.4 shared sound event detector (plan 6.1), retrained on the v0.4 training set.

Model: PANNs CNN14 DecisionLevelAtt (AudioSet weights), 16 kHz windows upsampled to 32 kHz, a new attention head for
seven classes (p1v4_data.DET_CLASSES): phone, doorbell, knock, footsteps, door, cabinet (cupboard or drawer), decoy.
The plan's "call" class is left out: the v0.4 training set has no family calls (they occur only in the report-only
cells of test and replication), so the class cannot be trained; other people's speech reaches every system through
the transcripts and speaker tags of the situation text (logged amendment, 2026-11-15).
Frame targets at 100 frames/s from the renderer's clip spans inside the window; loss = BCE on frame outputs + BCE on
clip outputs. SpecAugment off. Training as chosen for v0.3 on its dev set: whole network (lr 1e-4), 3 epochs, batch
16, AdamW (wd 0.01), 500 warm-up steps then cosine, bf16 autocast, gradient clip 5. The epoch is chosen on dev by
window-level macro F1 over the seven classes (a class is present in a window if its highest frame probability >= 0.5).

usage: python -X utf8 scripts/p1v4_sed.py train <out_dir>
       python -X utf8 scripts/p1v4_sed.py windows <checkpoint> train|dev <out_prefix>   (8 s windows: frames, embedding)
"""
import json
import math
import os
import sys
import time

import numpy as np
import soundfile as sf
import torch
import torch.nn as nn
import torch.nn.functional as F
from scipy.signal import resample_poly

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import p1v4_data as D  # noqa: E402

PANNS_DIR = os.path.abspath("data/models_dl/panns_d2f4b8c")
N_FRAMES = 801                 # 8 s at 32 kHz, hop 320, centred frames
FPS = 100
EPOCHS, BATCH, WARMUP, LR = 3, 16, 500, 1e-4


def build_model():
    sys.path.insert(0, PANNS_DIR)
    from models import AttBlock, Cnn14_DecisionLevelAtt
    m = Cnn14_DecisionLevelAtt(sample_rate=32000, window_size=1024, hop_size=320, mel_bins=64, fmin=50, fmax=14000,
                               classes_num=527)
    ck = torch.load(os.path.join(PANNS_DIR, "Cnn14_DecisionLevelAtt_mAP=0.425.pth"), map_location="cpu",
                    weights_only=True)
    m.load_state_dict(ck["model"])
    m.att_block = AttBlock(2048, len(D.DET_CLASSES), activation="sigmoid")
    m.spec_augmenter = nn.Identity()
    return m


def load(ckpt):
    m = build_model()
    m.load_state_dict(torch.load(ckpt, map_location="cpu", weights_only=True))
    return m.cuda().eval()


def forward(m, x):
    """x: (B, n) at 32 kHz -> framewise (B, frames, C), clipwise (B, C), embedding (B, 4096)."""
    from models import interpolate, pad_framewise_output
    x = m.logmel_extractor(m.spectrogram_extractor(x))
    frames = x.shape[2]
    x = m.bn0(x.transpose(1, 3)).transpose(1, 3)
    for blk in (m.conv_block1, m.conv_block2, m.conv_block3, m.conv_block4, m.conv_block5):
        x = F.dropout(blk(x, pool_size=(2, 2), pool_type="avg"), p=0.2, training=m.training)
    x = F.dropout(m.conv_block6(x, pool_size=(1, 1), pool_type="avg"), p=0.2, training=m.training)
    x = torch.mean(x, dim=3)
    x = F.max_pool1d(x, 3, 1, 1) + F.avg_pool1d(x, 3, 1, 1)
    x = F.dropout(x, p=0.5, training=m.training)
    h = F.relu_(m.fc1(x.transpose(1, 2)))                     # (B, T', 2048)
    emb = torch.cat([h.mean(1), h.amax(1)], 1)
    x = F.dropout(h.transpose(1, 2), p=0.5, training=m.training)
    clip, _, seg = m.att_block(x)
    frame = pad_framewise_output(interpolate(seg.transpose(1, 2), m.interpolate_ratio), frames)
    return frame, clip, emb


def to32(x):
    return resample_poly(x, 2, 1).astype(np.float32)


class Windows(torch.utils.data.Dataset):
    def __init__(self, wins):
        self.wins = wins

    def __len__(self):
        return len(self.wins)

    def __getitem__(self, i):
        w = self.wins[i]
        x = sf.read(w["path"], dtype="float32")[0]
        t = D.frame_targets(w["events"], N_FRAMES, FPS)
        return torch.from_numpy(to32(x)), torch.from_numpy(t), torch.from_numpy(t.max(0))


def loader(wins, shuffle, batch=BATCH, workers=6, seed=0):
    g = torch.Generator()
    g.manual_seed(seed)
    return torch.utils.data.DataLoader(Windows(wins), batch_size=batch, shuffle=shuffle, num_workers=workers,
                                       pin_memory=True, drop_last=shuffle, generator=g, persistent_workers=False)


@torch.no_grad()
def predict(m, wins, batch=32):
    m.eval()
    frames, embs = [], []
    for x, _, _ in loader(wins, False, batch):
        with torch.autocast("cuda", dtype=torch.bfloat16):
            f, _, e = forward(m, x.cuda(non_blocking=True))
        frames.append(f.float().cpu().numpy().astype(np.float16))
        embs.append(e.float().cpu().numpy().astype(np.float16))
    return np.concatenate(frames), np.concatenate(embs)


def window_f1(wins, frames, thr=0.5):
    pred = frames.astype(np.float32).max(1) >= thr                       # (N, C)
    gold = np.stack([D.frame_targets(w["events"], N_FRAMES, FPS).max(0) for w in wins]) > 0
    per = {}
    for c, name in enumerate(D.DET_CLASSES):
        tp = float((pred[:, c] & gold[:, c]).sum())
        fp = float((pred[:, c] & ~gold[:, c]).sum())
        fn = float((~pred[:, c] & gold[:, c]).sum())
        per[name] = {"f1": 2 * tp / max(1.0, 2 * tp + fp + fn), "n_gold": int(gold[:, c].sum()),
                     "n_pred": int(pred[:, c].sum())}
    none_ok = float(((~pred.any(1)) == (~gold.any(1))).mean())
    return {"macro_f1": float(np.mean([v["f1"] for v in per.values()])), "per_class": per,
            "none_agreement": none_ok}


def train(out_dir):
    os.makedirs(out_dir, exist_ok=True)
    torch.manual_seed(0)
    tr, _ = D.load_windows("train")
    dv, _ = D.load_windows("dev")
    print(f"train windows {len(tr)}, dev windows {len(dv)}", flush=True)
    m = build_model().cuda()
    params = [p for p in m.parameters() if p.requires_grad]
    opt = torch.optim.AdamW(params, lr=LR, weight_decay=0.01)
    steps = EPOCHS * (len(tr) // BATCH)
    sched = torch.optim.lr_scheduler.LambdaLR(
        opt, lambda s: min(1.0, (s + 1) / WARMUP) * 0.5 * (1 + math.cos(math.pi * min(1.0, s / steps))))
    log, best, step = [], -1.0, 0
    for ep in range(EPOCHS):
        m.train()
        t0, run = time.time(), []
        for x, ft, ct in loader(tr, True, seed=ep):
            x, ft, ct = x.cuda(non_blocking=True), ft.cuda(non_blocking=True), ct.cuda(non_blocking=True)
            with torch.autocast("cuda", dtype=torch.bfloat16):
                f, c, _ = forward(m, x)
            loss = (F.binary_cross_entropy(f.float().clamp(1e-6, 1 - 1e-6), ft)
                    + F.binary_cross_entropy(c.float().clamp(1e-6, 1 - 1e-6), ct))
            opt.zero_grad(set_to_none=True)
            loss.backward()
            torch.nn.utils.clip_grad_norm_(params, 5.0)
            opt.step()
            sched.step()
            step += 1
            run.append(loss.item())
            if step % 500 == 0:
                print(f"ep {ep} step {step}/{steps} loss {np.mean(run[-500:]):.4f} "
                      f"{(time.time() - t0) / len(run):.3f} s/step", flush=True)
        frames, _ = predict(m, dv)
        met = window_f1(dv, frames)
        met.update(epoch=ep, train_loss=float(np.mean(run)), minutes=round((time.time() - t0) / 60, 1))
        log.append(met)
        print(json.dumps(met), flush=True)
        if met["macro_f1"] > best:
            best = met["macro_f1"]
            torch.save(m.state_dict(), os.path.join(out_dir, "sed.pt"))
            json.dump({"epoch": ep, "macro_f1": best}, open(os.path.join(out_dir, "chosen.json"), "w"))
        json.dump(log, open(os.path.join(out_dir, "sed_log.json"), "w"), indent=1)
    print(f"best dev macro F1 {best:.4f}")


def windows(ckpt, which, out_prefix):
    wins, _ = D.load_windows(which)
    m = load(ckpt)
    frames, embs = predict(m, wins)
    os.makedirs(os.path.dirname(out_prefix), exist_ok=True)
    np.save(out_prefix + "_frames.npy", frames)
    np.save(out_prefix + "_emb.npy", embs)
    json.dump([w["id"] for w in wins], open(out_prefix + "_ids.json", "w"))
    if which == "dev":
        print(json.dumps(window_f1(wins, frames)))


if __name__ == "__main__":
    if sys.argv[1] == "train":
        train(sys.argv[2])
    elif sys.argv[1] == "windows":
        windows(*sys.argv[2:5])
    else:
        raise SystemExit(__doc__)
